use php_ext::request::Request;
use php_ext::values::{Owner, Value};

/// The row is given up by name, and the hook's answer is discarded by name.
pub(crate) fn forget_row(req: &mut Request, owner: Owner<Value>, hook: fn() -> i32) {
    let _answer = hook();
    owner.give_up(req);
}
